const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];

/* 0. SAFE IN-FRAME NAVIGATION — Prevent <a href="#..."> in srcdoc from navigating iframe to parent URL (white screen) */
if (!window.__zeusNavBound) {
  window.__zeusNavBound = true;
  document.addEventListener('click', (e) => {
    const link = e.target && e.target.closest ? e.target.closest('a[href]') : null;
    if (!link) return;
    const href = link.getAttribute('href') || '';
    e.preventDefault();
    if (href === '#' || href === '#top') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else if (href.startsWith('#')) {
      const id = href.slice(1);
      const target = document.getElementById(id) || document.querySelector(href);
      if (target) {
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
    try {
      parent.postMessage({ type: 'zeus-preview-nav', href, label: (link.textContent || '').trim() }, '*');
    } catch {}
  });
  document.addEventListener('submit', (e) => {
    if (!e.defaultPrevented) {
      e.preventDefault();
    }
  });
}

/* 1. MORROW ROASTERS — Menu Tabs, Pre-order Tray & Floor-Plan Booking */
let morrowTotal = 0;
let morrowItems = [];
let morrowZone = 'У панорамного окна';
let morrowSlot = '10:30';

$$('[data-menu-tab]').forEach((tab) => {
  tab.addEventListener('click', () => {
    const cat = tab.dataset.menuTab;
    $$('[data-menu-tab]').forEach((b) => b.classList.toggle('active', b === tab));
    $$('[data-menu-cat]').forEach((row) => {
      row.hidden = cat !== 'all' && row.dataset.menuCat !== cat;
    });
  });
});

$$('[data-dish]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const price = Number(btn.dataset.price || 0);
    morrowTotal += price;
    morrowItems.push(btn.dataset.dish);
    const bar = $('#morrow-order-bar');
    if (bar) bar.hidden = false;
    const sum = $('#morrow-order-sum');
    if (sum) sum.textContent = morrowTotal.toLocaleString('ru-RU') + ' ₽ · ' + morrowItems.length + ' поз.';
    const tray = $('#morrow-tray-count');
    if (tray) tray.textContent = String(morrowItems.length);
    btn.textContent = 'В счёте ✓';
  });
});

$('#morrow-order-clear')?.addEventListener('click', () => {
  morrowTotal = 0;
  morrowItems = [];
  const bar = $('#morrow-order-bar');
  if (bar) bar.hidden = true;
  const tray = $('#morrow-tray-count');
  if (tray) tray.textContent = '0';
  $$('[data-dish]').forEach((b) => { b.textContent = '+ В заказ'; });
});

$$('[data-zone]').forEach((z) => {
  z.addEventListener('click', () => {
    morrowZone = z.dataset.zone;
    $$('[data-zone]').forEach((el) => el.classList.toggle('active', el === z));
  });
});

$$('[data-slot]').forEach((sl) => {
  sl.addEventListener('click', () => {
    morrowSlot = sl.dataset.slot;
    $$('[data-slot]').forEach((el) => el.classList.toggle('active', el === sl));
  });
});

const booking = $('#booking-form');
if (booking) {
  booking.addEventListener('submit', (e) => {
    e.preventDefault();
    const status = $('#booking-status');
    if (status) {
      status.textContent = 'Столик (' + morrowZone + ', ' + morrowSlot + ') выбран. Заявки начнут приходить в «Базу» проекта после публикации сайта.';
      status.dataset.confirmed = 'true';
    }
  });
}

/* 2. FORM / OBJECT — Category Filter, Material Swatches & Interactive Cart */
const cart = [];
function renderCart() {
  const countEl = $('#cart-count');
  const listEl = $('#cart-list');
  const totalEl = $('#cart-total');
  const shipEl = $('#cart-ship-fill');
  if (countEl) countEl.textContent = String(cart.length);
  if (!listEl) return;
  if (!cart.length) {
    listEl.textContent = 'Пока пусто — добавьте предмет из каталога.';
    if (totalEl) totalEl.textContent = '0 ₽';
    if (shipEl) shipEl.style.width = '0%';
    return;
  }
  const sum = cart.reduce((acc, item) => acc + item.price, 0);
  listEl.textContent = cart.map((i) => i.name + ' (' + i.price.toLocaleString('ru-RU') + ' ₽)').join(' · ');
  if (totalEl) totalEl.textContent = sum.toLocaleString('ru-RU') + ' ₽';
  if (shipEl) shipEl.style.width = Math.min(100, Math.round((sum / 5000) * 100)) + '%';
}

$$('.buy').forEach((b) => {
  b.addEventListener('click', () => {
    cart.push({ name: b.dataset.name || 'Предмет', price: Number(b.dataset.price || 2400) });
    renderCart();
    b.textContent = 'Добавлено ✓';
  });
});

$('#cart-toggle')?.addEventListener('click', () => {
  const c = $('#cart');
  if (!c) return;
  c.hidden = !c.hidden;
  if (!c.hidden) c.scrollIntoView({ block: 'nearest' });
});

$('#cart-clear')?.addEventListener('click', () => {
  cart.length = 0;
  renderCart();
  $$('.buy').forEach((b) => { b.textContent = 'В корзину +'; });
});

$$('[data-shop-cat]').forEach((pill) => {
  pill.addEventListener('click', () => {
    const cat = pill.dataset.shopCat;
    $$('[data-shop-cat]').forEach((p) => p.classList.toggle('active', p === pill));
    $$('.product').forEach((card) => {
      card.hidden = cat !== 'all' && card.dataset.cat !== cat;
    });
  });
});

/* 3. NOMA WORKSPACE — Notes List, Live Editor, Checklist & Kanban Board */
const notes = [
  {
    title: 'Планы на неделю',
    tag: 'Спринт',
    body: $('#note-body')?.value || ''
  },
  {
    title: 'Архитектура релиза 2.0',
    tag: 'Продукт',
    body: '01  Собрать дизайн-токены и тёмную тему.\\n02  Проверить адаптив на 390px.\\n03  Выгрузить готовую сборку.'
  },
  {
    title: 'Заметки со встречи',
    tag: 'Команда',
    body: 'Фокус на скорости первого отклика: пользователь должен увидеть работающий экран без регистрации и длинных анкет.'
  }
];
let selected = 0;

function updateWordCount() {
  const body = $('#note-body')?.value || '';
  const words = body.trim() ? body.trim().split(/\\s+/).length : 0;
  const wc = $('#noma-words');
  if (wc) wc.textContent = words + ' сл.';
}

function noteList() {
  const list = $('#notes-list');
  if (!list) return;
  const query = ($('#note-search')?.value || '').toLowerCase().trim();
  list.replaceChildren();
  notes.forEach((note, i) => {
    if (query && !(note.title + ' ' + note.body).toLowerCase().includes(query)) return;
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'note' + (i === selected ? ' active' : '');
    const titleSpan = document.createElement('strong');
    titleSpan.textContent = note.title || 'Без названия';
    const metaSpan = document.createElement('small');
    metaSpan.textContent = note.tag || 'Личное';
    b.append(titleSpan, metaSpan);
    b.addEventListener('click', () => {
      selected = i;
      if ($('#note-title')) $('#note-title').value = notes[i].title;
      if ($('#note-body')) $('#note-body').value = notes[i].body;
      updateWordCount();
      noteList();
    });
    list.append(b);
  });
}

if ($('#notes-list')) {
  noteList();
  updateWordCount();
}

$('#note-search')?.addEventListener('input', noteList);

$('#new-note')?.addEventListener('click', () => {
  notes.unshift({ title: 'Новая заметка', tag: 'Черновик', body: '' });
  selected = 0;
  noteList();
  if ($('#note-title')) {
    $('#note-title').value = notes[0].title;
    $('#note-title').focus();
  }
  if ($('#note-body')) $('#note-body').value = '';
  updateWordCount();
});

['title', 'body'].forEach((key) => {
  $('#note-' + key)?.addEventListener('input', (e) => {
    notes[selected][key] = e.target.value;
    noteList();
    updateWordCount();
    const st = $('#note-status');
    if (st) st.textContent = 'Сохранено локально в текущем превью';
  });
});

$$('[data-noma-view]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const view = btn.dataset.nomaView;
    $$('[data-noma-view]').forEach((b) => b.classList.toggle('active', b === btn));
    const docPane = $('#noma-doc-pane');
    const boardPane = $('#noma-board-pane');
    if (docPane) docPane.hidden = view !== 'doc';
    if (boardPane) boardPane.hidden = view !== 'board';
  });
});

$$('[data-check-item]').forEach((chk) => {
  chk.addEventListener('click', () => {
    chk.classList.toggle('done');
    const done = $$('[data-check-item].done').length;
    const all = $$('[data-check-item]').length;
    const lbl = $('#noma-check-count');
    if (lbl) lbl.textContent = done + '/' + all + ' выполнено';
  });
});

/* 4. PULSE ANALYTICS — Period Switcher, Interactive Bars & Orders Filter */
const pulseData = {
  '7': { rev: '124 800 ₽', ord: '84', avg: '1 486 ₽', conv: '4.8%', bars: [38, 54, 47, 74, 62, 88, 100], delta: '↗ +18.4% к прошлой неделе' },
  '30': { rev: '512 400 ₽', ord: '345', avg: '1 485 ₽', conv: '5.4%', bars: [58, 44, 75, 66, 89, 77, 100], delta: '↗ +26.2% к прошлому месяцу' }
};

$('#period')?.addEventListener('change', (e) => {
  const d = pulseData[e.target.value] || pulseData['7'];
  if ($('#revenue')) $('#revenue').textContent = d.rev;
  if ($('#orders')) $('#orders').textContent = d.ord;
  if ($('#insight-orders')) $('#insight-orders').textContent = d.ord;
  if ($('#avg-check')) $('#avg-check').textContent = d.avg;
  if ($('#conv-rate')) $('#conv-rate').textContent = d.conv;
  if ($('#rev-delta')) $('#rev-delta').textContent = d.delta;
  $$('.chart i').forEach((bar, i) => {
    bar.style.height = d.bars[i] + '%';
  });
});

$$('[data-order-filter]').forEach((btn) => {
  btn.addEventListener('click', () => {
    const f = btn.dataset.orderFilter;
    $$('[data-order-filter]').forEach((b) => b.classList.toggle('active', b === btn));
    $$('[data-order-status]').forEach((row) => {
      row.hidden = f !== 'all' && row.dataset.orderStatus !== f;
    });
  });
});

/* 5. STUDIO FORMA — Case Inspector & Scope Calculator */
$$('[data-work]').forEach((b) => {
  b.addEventListener('click', () => {
    const d = $('#work-detail');
    if (!d) return;
    d.hidden = false;
    $$('[data-work]').forEach((el) => el.classList.toggle('active', el === b));
    d.replaceChildren();
    const badge = document.createElement('small');
    badge.textContent = 'РАЗБОР ПРОЕКТА · ' + (b.dataset.year || '2026');
    const heading = document.createElement('h3');
    heading.textContent = b.dataset.work || '';
    const copy = document.createElement('p');
    copy.textContent = (b.dataset.detail || '') + ' — ' + (b.dataset.outcome || 'Полный цикл арт-дирекшна, типографики и фронтенд-разработки.');
    d.append(badge, heading, copy);
    d.scrollIntoView({ block: 'nearest' });
  });
});

$$('[data-scope]').forEach((chip) => {
  chip.addEventListener('click', () => {
    chip.classList.toggle('active');
    const total = $$('[data-scope].active').reduce((s, el) => s + Number(el.dataset.scope || 0), 0);
    const out = $('#forma-estimate');
    if (out) out.textContent = total ? 'Ориентир бюджета: от ' + total.toLocaleString('ru-RU') + ' ₽' : 'Выберите модули проекта выше';
  });
});

/* 6. SLOT BARBER — Master Picker & Multi-Step Concierge Bot */
let slotService = '';
let slotMaster = 'Алексей · Топ-барбер';
const botOptions = $('#bot-options');
const botLog = $('#bot-log');

$$('[data-master]').forEach((m) => {
  m.addEventListener('click', () => {
    slotMaster = m.dataset.master || slotMaster;
    $$('[data-master]').forEach((el) => el.classList.toggle('active', el === m));
    const badge = $('#slot-active-master');
    if (badge) badge.textContent = slotMaster;
  });
});

function say(text, user = false) {
  if (!botLog) return;
  const b = document.createElement('div');
  b.className = 'bubble' + (user ? ' user' : '');
  b.textContent = text;
  botLog.append(b);
}

function renderInitialBotServices() {
  if (!botOptions) return;
  botOptions.replaceChildren();
  [
    ['Стрижка', 'Стрижка · 1 500 ₽', 'btn'],
    ['Борода', 'Борода · 800 ₽', 'btn secondary'],
    ['Комплекс', 'Комплекс · 2 100 ₽', 'btn secondary']
  ].forEach(([srv, label, cls]) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = cls;
    b.dataset.service = srv;
    b.textContent = label;
    botOptions.append(b);
  });
}

botOptions?.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  if (b.dataset.service) {
    slotService = b.dataset.service;
    say(b.textContent, true);
    say('Мастер: ' + slotMaster + '. Выберите удобное окно сегодня:');
    botOptions.replaceChildren();
    ['10:00', '12:30', '16:00', '19:30'].forEach((time) => {
      const t = document.createElement('button');
      t.type = 'button';
      t.className = 'btn secondary';
      t.dataset.time = time;
      t.textContent = time;
      botOptions.append(t);
    });
  } else if (b.dataset.time) {
    say(b.dataset.time, true);
    say(slotService + ' у мастера (' + slotMaster + ') в ' + b.dataset.time + '. Записи будут приходить в «Базу» проекта после подключения бота.');
    botOptions.replaceChildren();
  }
});

$('#bot-reset')?.addEventListener('click', () => {
  slotService = '';
  botLog?.replaceChildren();
  renderInitialBotServices();
});
